FUNCTION f : TOD
f := TOD#12:30;
END_FUNCTION

FUNCTION f : INT
VAR_INPUT a : INT; END_VAR
VAR i : INT; END_VAR
CASE a OF 1: f := 1; ENDCASE;
FOR i := 1 TO 2 DO f := f + 1; ENDFOR;
WHILE f < 9 DO f := f + 1; ENDWHILE;
REPEAT f := f + 1; UNTIL f > 10 ENDREPEAT;
END_FUNCTION

FUNCTION f : INT
f := Tc2_Standard.LEN('ab');
END_FUNCTION

FUNCTION f : INT
VAR p : POINTER TO BYTE; x : ARRAY[0..3] OF BYTE := [10, 20, 30, 40]; END_VAR
p := ADR(x) + 1; f := BYTE_TO_INT(p^);
END_FUNCTION
FUNCTION main : DINT
printf('%d$N', f());
main := 0;
END_FUNCTION
